private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (str == null)
        return suffix == null;
    if (suffix == null)
        return false;
    if (ignoreCase) {
        int suflen = suffix.length();
        int fromIndex = str.length() - suflen;
        if (fromIndex < 0)
            return false;
        return str.regionMatches(true, fromIndex, suffix, 0, suflen);
    } else {
        return str.endsWith(suffix);
    }
}

