@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    // Create a list of all vertices from the resultMap
    List<V> vertices = new ArrayList<>(resultMap.values());
    int total = vertices.size();
    // Split the vertices into two partitions: first half and second half
    int split = total / 2;
    // If an odd number of vertices, the first partition gets the extra vertex
    // Build a complete bipartite graph between the two partitions
    for (int i = 0; i < split; i++) {
        V left = vertices.get(i);
        for (int j = split; j < total; j++) {
            V right = vertices.get(j);
            // Add an undirected edge between left and right
            target.addEdge(left, right);
        }
    }
}

