private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Construct a circulator that starts at the supplied node and follows the specified direction.
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // Current position will advance along the outer face until a node satisfies the predicate
    // or the stop node is encountered.  The circulator is positioned at the node that
    // satisfies the predicate, or at the stop node if none satisfy the predicate.
    Node current = start;
    while (true) {
        if (predicate.test(current)) {
            circ.setCurrent(current);  // Move the circulator to the matching node
            return circ;
        }
        if (current == stop) {
            circ.setCurrent(stop);     // Fall back to the stop node if nothing matches
            return circ;
        }
        // Move to the next node around the outer face.
        current = circ.next();        // Advance according to the circulator logic
    }
}

